def findLHS(nums):
    # Create a hash map to store each number's frequency
    freq = {}
    for num in nums:
        if num not in freq:
            freq[num] = 0
        freq[num] += 1

    max_len = 0
    # For each number, check if there exists num + 1
    for num in freq:
        if num + 1 in freq:
            curr_len = freq[num] + freq[num + 1]
            if curr_len > max_len:
                max_len = curr_len
    return max_len
